CREATE TABLE emp (id INT NOT NULL, mgr INT, FOREIGN KEY (mgr) REFERENCES emp (id), PRIMARY KEY (id));
CREATE TABLE emp2 (id INT NOT NULL, code VARCHAR(10), parent_code VARCHAR(10), CONSTRAINT fk FOREIGN KEY (parent_code) REFERENCES emp2 (code), UNIQUE KEY uq (code), PRIMARY KEY (id));
CREATE TABLE e12 (id INT NOT NULL, mgr INT, KEY k (id));
ALTER TABLE e12 ADD FOREIGN KEY (mgr) REFERENCES e12 (id), ADD UNIQUE KEY u (id);
CREATE TABLE e10 (id INT NOT NULL, mgr INT, PRIMARY KEY (id));
ALTER TABLE e10 DROP PRIMARY KEY, ADD PRIMARY KEY (id), ADD FOREIGN KEY (mgr) REFERENCES e10 (id);
